"""Generates the combat-light research capture test (three modes per view).

Writes <out>/combat_lighting.test.sqf and .toml. Every triScreenshot must be a
top-level statement with a literal label, so the shot lines are spelled out.

Modes: classic | remastered (combatLights=0) | combat (combatLights=1).
"""
import argparse
import os
import shutil

HERE = os.path.dirname(os.path.abspath(__file__))

MODES = [("classic", "c"), ("remastered", "r"), ("combat", "x")]

HEAD = r'''// RESEARCH (track combat): Classic | Remastered | Remastered + combat lights.
// Generated by tmp/research/combat/scripts/gen_test.py. Not committed.
#include "capture_lib.sqf"

triSimUntil { alive player }

capWorld = "Abel"
capFov = 0.7
capSimT = 0
capPinTime = false
capUseView = false
capProps = []
capView = "setup"
capModeName = "none"
capLit = "none"
capLitC = "none"
capGpu = "none"
capPerf = "none"
capFW = []
capFE = []
capBurnV = objNull
capFire = objNull

// "classic" | "remastered" | "combat" call capMode3
capMode3 = {
    if (_this == "combat_ns") then {
        capLitC = triSetLighting "combatLights=%COMBAT%";
        capLitS = triSetLighting "combatScatter=0";
        "remastered" call capMode;
        capModeName = "combat_ns";
    };
    if (_this == "combat") then {
        capLitS = triSetLighting "combatScatter=1";
        capLitC = triSetLighting "combatLights=%COMBAT%";
        "remastered" call capMode;
        capModeName = "combat";
    };
    if ((_this == "classic") or (_this == "remastered")) then {
        capLitC = triSetLighting "combatLights=0";
        _this call capMode;
    };
    format ["view=%1;event=mode3;mode=%2;combat=%3", capView, capModeName, capLitC] call capLog;
}
// [units] call capVolley: everyone in the list fires his primary weapon now.
capVolley = { { _x fire (primaryWeapon _x) } forEach _this }
capEngageN = {
    private ["_i"];
    if (((count capFW) > 0) and ((count capFE) > 0)) then {
        { (capFW select 0) reveal _x } forEach capFE;
        { (capFE select 0) reveal _x } forEach capFW;
        _i = 0;
        { _x doFire (capFE select (_i mod (count capFE))); _i = _i + 1 } forEach capFW;
        _i = 0;
        { _x doFire (capFW select (_i mod (count capFW))); _i = _i + 1 } forEach capFE;
    };
}
capBoom = {
    private ["_p"];
    _p = _this call capRel;
    capShell = createShell ["Shell120", [_p select 0, _p select 1, 40], [0, 0, -250], player, objNull];
}
capBurn = { if (not (isNull capBurnV)) then { capBurnV inflame true } }
capClearAll = {
    [] call capClear;
    capFW = [];
    capFE = [];
}

triCaptureAtPresent true
triSetMsaa 4
triSetRenderScale 1.5
showCinemaBorder false
enableRadio false
player setCaptive true
player allowDamage false

createCenter west
createCenter east
capGrpW = createGroup west
capProbe = "HeliHEmpty" createVehicle [7300, 10900, 0]
capCam = "camera" camCreate [7300, 10900, 2]
capCam cameraEffect ["internal", "back"]
triSimFrames 240
'''


def shot(lines, label):
    lines.append(f'triScreenshot "{label}"')
    lines.append(f'"{label}" call capRecord')


def frames(lines, n):
    lines.append(f"triSimFrames {n}")


def view_ffd(lines):
    """Dusk firefight: the committed firefight_1..3 layout, AI fire, two shells."""
    lines.append('["ffd", 7600, 10850, 2, 0, 0, [1985, 7, 5, 19, 35], 0, 0, 1000] call capBegin')
    lines.append(r'''capFFStageD = {
    capGrpFW = createGroup west;
    capGrpFE = createGroup east;
    east setFriend [west, 0];
    west setFriend [east, 0];
    capFW = [];
    capFE = [];
    { capNew = [["SoldierWB"], _x select 0, _x select 1, 90, "fighter", capGrpFW] call capSpawn; if (not (isNull capNew)) then { capFW = capFW + [capNew] } } forEach [[24, -15], [26, -12], [23, -9], [27, -6]];
    { capNew = [["SoldierEB"], _x select 0, _x select 1, -90, "fighter", capGrpFE] call capSpawn; if (not (isNull capNew)) then { capFE = capFE + [capNew] } } forEach [[25, 9], [28, 12], [24, 15]];
    capBurnV = [["Ural", "Truck5t"], 60, 24, 30, "veh"] call capSpawn;
    if (not (isNull capBurnV)) then { capBurnV allowDamage true; capBurnV setDammage 1; capBurnV inflame true };
}''')
    for mode, m in MODES:
        lines.append("[] call capFFStageD")
        lines.append(f'"{mode}" call capMode3')
        lines.append("[] call capEngageN")
        frames(lines, 200)
        lines.append("[] call capReadTimers")
        lines.append("call { [] call capPinEnv; [] call capPinView; [] call capEngageN; [] call capBurn }")
        lines.append("[62, -2] call capBoom")
        for i, n in enumerate([4, 4, 4, 8]):
            frames(lines, n)
            shot(lines, f"ffd_{m}_1{'abcd'[i]}")
        lines.append("[] call capEngageN")
        lines.append("[58, -32] call capBoom")
        for i, n in enumerate([6, 6]):
            frames(lines, n)
            shot(lines, f"ffd_{m}_2{'ab'[i]}")
        lines.append("[] call capEngageN")
        for i, n in enumerate([20, 3, 3]):
            frames(lines, n)
            shot(lines, f"ffd_{m}_3{'abc'[i]}")
        lines.append("[] call capClearAll")
        frames(lines, 30)


def view_ffn(lines, name="ffn", date="[1985, 7, 12, 23, 0]", modes=None):
    """Moonless night firefight, closer: scripted volleys, a shell, a wreck, a campfire."""
    modes = modes or MODES + [("combat_ns", "y")]
    lines.append(f'["{name}", 7600, 10850, 1.8, 0, -2, {date}, 0, 0, 1000] call capBegin')
    lines.append("capPinTime = false")
    lines.append(r'''capFFStageN = {
    capGrpFW = createGroup west;
    capGrpFE = createGroup east;
    capFW = [];
    capFE = [];
    { capNew = [["SoldierWB"], _x select 0, _x select 1, 70, "fighter", capGrpFW] call capSpawn; if (not (isNull capNew)) then { capFW = capFW + [capNew] } } forEach [[13, -7], [15.5, -4.5], [12.5, -2.5]];
    { capNew = [["SoldierEB"], _x select 0, _x select 1, -110, "fighter", capGrpFE] call capSpawn; if (not (isNull capNew)) then { capFE = capFE + [capNew] } } forEach [[16, 3.5], [18, 6], [15, 8.5]];
    capBurnV = [["Ural", "Truck5t"], 36, 13, 30, "veh"] call capSpawn;
    if (not (isNull capBurnV)) then { capBurnV allowDamage true; capBurnV setDammage 1; capBurnV inflame true };
    capFire = [["Fire"], 21, -12, 0, "veh"] call capSpawn;
    if (not (isNull capFire)) then { capFire inflame true };
}''')
    for mode, m in modes:
        lines.append("[] call capFFStageN")
        lines.append(f'"{mode}" call capMode3')
        frames(lines, 150)
        lines.append("[] call capReadTimers")
        lines.append("call { [] call capPinEnv; [] call capPinView; [] call capBurn; if (not (isNull capFire)) then { capFire inflame true } }")
        frames(lines, 3)
        shot(lines, f"{name}_{m}_0")
        lines.append("capFW call capVolley")
        for i, n in enumerate([2, 2, 2, 3, 4]):
            frames(lines, n)
            shot(lines, f"{name}_{m}_v1{'abcde'[i]}")
        frames(lines, 30)
        lines.append("(capFW + capFE) call capVolley")
        for i, n in enumerate([2, 2, 2, 3, 4]):
            frames(lines, n)
            shot(lines, f"{name}_{m}_v3{'abcde'[i]}")
        frames(lines, 30)
        lines.append("[40, -6] call capBoom")
        for i, n in enumerate([4, 4, 4, 6, 10, 20]):
            frames(lines, n)
            shot(lines, f"{name}_{m}_b{i + 1}")
        # sustained fire, for the GPU cost under load
        lines.append("[] call capEngageN")
        frames(lines, 150)
        lines.append("[] call capReadTimers")
        for i in range(6):
            frames(lines, 2)
            shot(lines, f"{name}_{m}_s{i + 1}")
        lines.append("[] call capClearAll")
        frames(lines, 30)


def view_muz(lines):
    """Muzzle-flash close-up at night: a rifleman and an MG gunner firing across the frame."""
    lines.append('["muz", 7640, 10860, 1.6, 20, -4, [1985, 7, 12, 23, 0], 0, 0, 800] call capBegin')
    lines.append("capPinTime = false")
    lines.append(r'''capMuzStage = {
    capGrpFW = createGroup west;
    capFW = [];
    capFE = [];
    { capNew = [[_x select 2], _x select 0, _x select 1, -80, "fighter", capGrpFW] call capSpawn; if (not (isNull capNew)) then { capFW = capFW + [capNew] } } forEach [[6.5, 1.2, "SoldierWB"], [9.5, -1.8, "SoldierWMG"]];
}''')
    for mode, m in MODES:
        lines.append("[] call capMuzStage")
        lines.append(f'"{mode}" call capMode3')
        frames(lines, 120)
        lines.append("[] call capReadTimers")
        lines.append("call { [] call capPinEnv; [] call capPinView }")
        frames(lines, 3)
        shot(lines, f"muz_{m}_0")
        for k in range(2):
            lines.append("capFW call capVolley")
            for i, n in enumerate([2, 2, 2, 3, 4]):
                frames(lines, n)
                shot(lines, f"muz_{m}_f{k + 1}{'abcde'[i]}")
            frames(lines, 25)
        lines.append("[] call capClearAll")
        frames(lines, 20)


def view_town(lines):
    """town_night with its campfire: fire flicker and the smoke lit from inside."""
    lines.append('["town", 7152, 8915, 1.75, 345, 3, [1985, 2, 27, 22, 0], 0, 0, 800] call capBegin')
    lines.append(r'''call {
    capFire = [["Fire"], 9, 3, 0, "veh"] call capSpawn;
    if (not (isNull capFire)) then { capFire inflame true };
}''')
    frames(lines, 150)
    for mode, m in MODES:
        lines.append(f'"{mode}" call capMode3')
        frames(lines, 90)
        lines.append("[] call capReadTimers")
        lines.append("[] call capPin")
        lines.append("call { if (not (isNull capFire)) then { capFire inflame true } }")
        for i, n in enumerate([3, 7, 11]):
            frames(lines, n)
            shot(lines, f"town_{m}_{i + 1}")
    lines.append("[] call capClearAll")


def view_cost(lines):
    """GPU cost under sustained fire: the ffn scene, combat lights off/on alternated."""
    lines.append('["cost", 7600, 10850, 1.8, 0, -2, [1985, 7, 12, 23, 0], 0, 0, 1000] call capBegin')
    lines.append("capPinTime = false")
    lines.append(r'''capCost = {
    capLitC = triSetLighting (format ["combatLights=%1", _this]);
    capGpuOff = triGpuTimes false;
    capGpuOn = triGpuTimes true;
    capPerfRes = triPerfReset 0;
    capModeName = format ["cost%1", _this];
}''')
    lines.append("[] call capFFStageN")
    lines.append('"combat" call capMode3')
    lines.append("[] call capEngageN")
    frames(lines, 120)
    lines.append("call { [] call capPinEnv; [] call capPinView }")
    for k in range(3):
        for val, m in (("0", "r"), ("1", "x")):
            lines.append(f'"{val}" call capCost')
            lines.append("[] call capEngageN")
            frames(lines, 150)
            lines.append("[] call capReadTimers")
            shot(lines, f"cost_{m}_{k + 1}")
    lines.append("[] call capClearAll")


def view_ffday(lines):
    view_ffn(lines, name="ffday", date="[1985, 7, 5, 12, 30]", modes=MODES)


VIEWS = {"ffd": view_ffd, "ffn": view_ffn, "muz": view_muz, "town": view_town, "ffday": view_ffday, "cost": view_cost}

TOML = '''# RESEARCH (track combat). Generated; not committed.
binary = "PoseidonGame"
mission = "tests/rendering/captures/missions/udcap_abel.Abel"
tags = ["lighting_capture", "headful", "exclusive"]
timeout = 900
assert_timeout = 180
extra_args = ["--no-strict", "--display-mode", "windowed", "--width", "960", "--height", "640"]
'''


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--out", required=True)
    ap.add_argument("--name", default="combat_lighting")
    ap.add_argument("--views", default="ffd,ffn,muz,town")
    ap.add_argument("--combat", default="1")
    ap.add_argument("--lib", required=True, help="capture_lib.sqf to copy beside the test")
    a = ap.parse_args()
    os.makedirs(a.out, exist_ok=True)
    lines = [HEAD.replace("%COMBAT%", a.combat)]
    for v in a.views.split(","):
        VIEWS[v](lines)
    lines.append('call { "view=done;event=done" call capLog }')
    lines.append("triEndTest")
    with open(os.path.join(a.out, a.name + ".test.sqf"), "w", newline="\n") as f:
        f.write("\n".join(lines) + "\n")
    with open(os.path.join(a.out, a.name + ".test.toml"), "w", newline="\n") as f:
        f.write(TOML)
    shutil.copyfile(a.lib, os.path.join(a.out, "capture_lib.sqf"))
    print("wrote", a.out, a.name)


if __name__ == "__main__":
    main()
